prediction.hop2_query:
SELECT ?film ?actor ?role ?year ?director ?other_film
WHERE {
  ?film rdf:type dbo:Film ;
        rdfs:label ?film_name ;
        dbo:starring ?actor ;
        dbo:director ?director ;
        dbo:releaseDate ?release_date .
  ?actor rdfs:label ?actor_name .
  ?director rdfs:label ?director_name .
  ?film dbo:producer ?producer .
  FILTER(CONTAINS(?film_name, "Crimson Peak") &&
         CONTAINS(?actor_name, "Burn Gorman") &&
         CONTAINS(?role, "Mr. Holly") &&
         ?release_date >= "2015-01-01"^^xsd:dateTime &&
         ?release_date < "2016-01-01"^^xsd:dateTime &&
         CONTAINS(?director_name, "Guillermo del Toro") &&
         CONTAINS(?other_film, "Pacific Rim"))
}
